import json, subprocess, sys, datetime
from collections import Counter

REPO_QUERY = "repo:cli/cli"
PR_QUERY = f"{REPO_QUERY} is:pr created:2024-12-01..2024-12-31"
ISSUE_QUERY = f"{REPO_QUERY} is:issue created:2024-12-01..2024-12-31"

PR_GQL = r'''
query($cursor: String) {
  search(type: ISSUE, query: "''' + PR_QUERY + r'''", first: 100, after: $cursor) {
    pageInfo { hasNextPage endCursor }
    nodes {
      ... on PullRequest {
        number
        createdAt
        mergedAt
        state
        author { login }
      }
    }
  }
}
'''

ISSUE_GQL = r'''
query($cursor: String) {
  search(type: ISSUE, query: "''' + ISSUE_QUERY + r'''", first: 100, after: $cursor) {
    pageInfo { hasNextPage endCursor }
    nodes {
      ... on Issue {
        number
        createdAt
        closedAt
        state
        labels(first: 100) { nodes { name } }
      }
    }
  }
}
'''

def run_paginated(gql):
    cmd = ["gh", "api", "graphql", "--paginate", "-f", f"query={gql}", "--jq", ".data.search.nodes[]"]
    proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
    nodes = []
    for line in proc.stdout:
        line = line.strip()
        if not line:
            continue
        nodes.append(json.loads(line))
    stderr = proc.stderr.read()
    rc = proc.wait()
    if rc != 0:
        raise RuntimeError(f"gh api graphql failed: {stderr}")
    return nodes

pr_nodes = run_paginated(PR_GQL)
issue_nodes = run_paginated(ISSUE_GQL)

# PR metrics
pr_total = len(pr_nodes)
merged_prs = [pr for pr in pr_nodes if pr.get("mergedAt")]
pr_merged = len(merged_prs)
pr_closed = len([pr for pr in pr_nodes if pr.get("state") == "CLOSED" and not pr.get("mergedAt")])

def parse_dt(s):
    return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))

merge_days = []
for pr in merged_prs:
    created = parse_dt(pr["createdAt"])
    merged = parse_dt(pr["mergedAt"])
    delta_days = (merged - created).total_seconds() / 86400
    merge_days.append(delta_days)

avg_merge_days = round(sum(merge_days) / len(merge_days), 1) if merge_days else 0.0

author_counts = Counter()
for pr in pr_nodes:
    author = (pr.get("author") or {}).get("login")
    if author:
        author_counts[author] += 1

if author_counts:
    top_contributor = author_counts.most_common(1)[0][0]
else:
    top_contributor = ""

# Issue metrics
issue_total = len(issue_nodes)

def is_bug(labels):
    for name in labels:
        if "bug" in name.lower():
            return True
    return False

bug_issues = []
for issue in issue_nodes:
    labels = [n["name"] for n in issue.get("labels", {}).get("nodes", [])]
    if is_bug(labels):
        bug_issues.append(issue)

issue_bug = len(bug_issues)

# resolved bugs closed during Dec 2024
start = datetime.datetime(2024, 12, 1, tzinfo=datetime.timezone.utc)
end = datetime.datetime(2024, 12, 31, 23, 59, 59, tzinfo=datetime.timezone.utc)

resolved_bugs = 0
for issue in bug_issues:
    closed_at = issue.get("closedAt")
    if not closed_at:
        continue
    closed_dt = parse_dt(closed_at)
    if start <= closed_dt <= end:
        resolved_bugs += 1

report = {
    "pr": {
        "total": pr_total,
        "merged": pr_merged,
        "closed": pr_closed,
        "avg_merge_days": float(avg_merge_days),
        "top_contributor": top_contributor,
    },
    "issue": {
        "total": issue_total,
        "bug": issue_bug,
        "resolved_bugs": resolved_bugs,
    },
}

with open("/app/report.json", "w", encoding="utf-8") as f:
    json.dump(report, f, indent=2, sort_keys=False)

print(json.dumps(report, indent=2))
